package com.johnny.hotel.inspection;import com.johnny.hotel.common.Result;import com.johnny.hotel.pagination.PageResult;import jakarta.validation.Valid;import lombok.RequiredArgsConstructor;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/housekeeping/inspections") @RequiredArgsConstructor @PreAuthorize("hasAnyRole('STAFF','MANAGER','OWNER','SUPER_ADMIN')") public class InspectionController{private final InspectionService service;@GetMapping("/{id}")public Result<RoomInspection> get(@PathVariable Long id){return Result.success(service.get(id));}@GetMapping public Result<PageResult<RoomInspection>> page(@RequestParam(required=false)Long roomId,@RequestParam(required=false)Long stayId,@RequestParam(required=false)Long employeeId,@RequestParam(required=false)Integer status,@RequestParam(required=false)Integer page,@RequestParam(required=false)Integer pageSize){return Result.success(service.page(roomId,stayId,employeeId,status,page,pageSize));}@PostMapping("/{id}/decision")public Result<RoomInspection> decide(@PathVariable Long id,@Valid @RequestBody InspectionRequests.Decide r){return Result.success(service.decide(id,r));}}
